// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address deployer;
    MockToken token;

    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new PoCGame(address(this), 0); vm.stopPrank(); deployer = __invmut_eoa; }

    function testFuzz_property(bool shouldSucceed, address tokenOwner, uint tokens) public {
        token = new MockToken(shouldSucceed);
        vm.prank(deployer);
        bool ok = c.transferAnyERC20Token(address(token), tokenOwner, tokens);
        // The success flag returned to the caller must mirror the token's transfer outcome.
        assertTrue(ok == shouldSucceed);
    }
}

contract MockToken {
    bool public succeed;
    constructor(bool s) { succeed = s; }
    function transfer(address to, uint256 tokens) public returns (bool success) {
        return succeed;
    }
}
